// The pure rules of Save Picture (docs/CAPTURE.md "Save picture", docs/UX.md "Save picture"): the
// image formats, the file names, and the part of a tile's picture a saved picture holds. The naming
// vectors are fixtures/synthetic/capture-names.json, generated by the Rust rules (crates/capture) and
// read here and by the Mac app's tests, so the three agree. Characters are Unicode scalars, as
// Rust's char. No file system, clock, or GPU here.

using System.Globalization;
using System.Text;

namespace NvrView.Tiles;

/// <summary>The image formats a saved picture can have: PNG, or JPEG at quality 0.9.</summary>
public enum PictureFormat
{
    Png,
    Jpeg,
}

public static class PictureFormats
{
    /// <summary>The quality JPEG pictures are written at.</summary>
    public const double JpegQuality = 0.9;

    /// <summary>The file extension without the dot: png or jpg.</summary>
    public static string Extension(this PictureFormat f) => f == PictureFormat.Png ? "png" : "jpg";

    /// <summary>The title in Settings and the save picker.</summary>
    public static string Title(this PictureFormat f) => f == PictureFormat.Png ? "PNG" : "JPEG";

    /// <summary>The setting's stored word: png or jpeg.</summary>
    public static string Key(this PictureFormat f) => f == PictureFormat.Png ? "png" : "jpeg";

    /// <summary>The format a stored word says; PNG for anything else.</summary>
    public static PictureFormat FromKey(string? key) => key == "jpeg" ? PictureFormat.Jpeg : PictureFormat.Png;

    /// <summary>The format a file name's extension says (.png, .jpg, .jpeg), or null.</summary>
    public static PictureFormat? FromExtension(string? extension) =>
        (extension ?? "").TrimStart('.').ToLowerInvariant() switch
        {
            "png" => PictureFormat.Png,
            "jpg" or "jpeg" => PictureFormat.Jpeg,
            _ => null,
        };
}

/// <summary>
/// The names of saved pictures: <c>YYYY-MM-DD HH.MM.SS.mmm camera.png</c>, the camera name sanitized, the whole
/// stem at most 120 characters, <c>Camera A</c> with share-safe names, and <c> (2)</c>, <c> (3)</c> before the
/// extension when the name is taken.
/// </summary>
public static class PictureNaming
{
    /// <summary>The longest sanitized name, in characters.</summary>
    public const int MaxNameChars = 120;

    /// <summary>Names tried before giving up.</summary>
    public const int MaxTries = 1000;

    /// <summary>The neutral name share-safe names use.</summary>
    public const string ShareSafeLabel = "Camera A";

    /// <summary>
    /// Replaces characters that are not allowed in file names, collapses runs of spaces, trims what Windows rejects
    /// at the ends, and caps the length; <c>_</c> when nothing is left.
    /// </summary>
    public static string Sanitize(string name)
    {
        var runes = new List<Rune>();
        foreach (Rune original in name.EnumerateRunes())
        {
            Rune c = original;
            if (c.Value is '/' or '\\' or ':' or '*' or '?' or '"' or '<' or '>' or '|')
            {
                c = new Rune('-');
            }
            else if (Rune.IsControl(c))
            {
                c = new Rune(' ');
            }
            if (c.Value == ' ' && runes.Count > 0 && runes[^1].Value == ' ')
            {
                continue;
            }
            runes.Add(c);
        }
        while (runes.Count > 0 && Rune.IsWhiteSpace(runes[0]))
        {
            runes.RemoveAt(0);
        }
        while (runes.Count > 0 && Rune.IsWhiteSpace(runes[^1]))
        {
            runes.RemoveAt(runes.Count - 1);
        }
        if (runes.Count > MaxNameChars)
        {
            runes.RemoveRange(MaxNameChars, runes.Count - MaxNameChars);
        }
        while (runes.Count > 0 && runes[^1].Value is '.' or ' ')
        {
            runes.RemoveAt(runes.Count - 1);
        }
        if (runes.Count == 0)
        {
            return "_";
        }
        var sb = new StringBuilder();
        foreach (Rune r in runes)
        {
            sb.Append(r.ToString());
        }
        return sb.ToString();
    }

    /// <summary>The camera's name as it appears in a file name: its own, or <c>Camera A</c> when share-safe.</summary>
    public static string CameraLabel(string camera, bool shareSafe) => shareSafe ? ShareSafeLabel : camera;

    /// <summary>Milliseconds since the Unix epoch of the clock on the wall at <paramref name="at"/> (the "local naive" time the stamp is made from).</summary>
    public static long LocalMillis(DateTimeOffset at) => at.ToUnixTimeMilliseconds() + (long)at.Offset.TotalMilliseconds;

    /// <summary><c>2026-10-11 17.02.03.250</c> from local naive milliseconds.</summary>
    public static string Stamp(long localMillis) =>
        DateTimeOffset.FromUnixTimeMilliseconds(localMillis).UtcDateTime.ToString("yyyy-MM-dd HH.mm.ss.fff", CultureInfo.InvariantCulture);

    /// <summary>
    /// The first name, <c>stamp camera.png</c>, then <c>stamp camera (2).png</c> and so on, for which
    /// <paramref name="taken"/> (asked with the file name) is false; null if every try is taken.
    /// </summary>
    public static string? FileName(long localMillis, string camera, bool shareSafe, PictureFormat format, Func<string, bool> taken)
    {
        string stem = Sanitize($"{Stamp(localMillis)} {CameraLabel(camera, shareSafe)}");
        string ext = format.Extension();
        string first = $"{stem}.{ext}";
        if (!taken(first))
        {
            return first;
        }
        for (int n = 2; n <= MaxTries; n++)
        {
            string candidate = $"{stem} ({n}).{ext}";
            if (!taken(candidate))
            {
                return candidate;
            }
        }
        return null;
    }
}

/// <summary>A whole-pixel rectangle of a picture, origin at the top left.</summary>
public readonly record struct PixelRegion(int X, int Y, int Width, int Height);

/// <summary>
/// What part of a tile's picture a saved picture holds: the whole picture, or the region a zoomed (or cropped)
/// tile shows now, at the source's resolution and never enlarged. Pictures are the visible rectangle (no padding),
/// the same pixels the renderer's source rectangles use.
/// </summary>
public static class PictureRegion
{
    /// <summary>The whole picture.</summary>
    public static PixelRegion Whole(int pictureWidth, int pictureHeight) => new(0, 0, Math.Max(pictureWidth, 0), Math.Max(pictureHeight, 0));

    /// <summary>
    /// The region of a <paramref name="pictureWidth"/> x <paramref name="pictureHeight"/> picture that a tile
    /// <paramref name="tileWidth"/> x <paramref name="tileHeight"/> (any unit) shows at <paramref name="zoom"/>
    /// and <paramref name="fill"/>, rounded to whole pixels and kept inside the picture. At 1x without a crop it is the
    /// whole picture; null when there is no picture.
    /// </summary>
    public static PixelRegion? Visible(int pictureWidth, int pictureHeight, double tileWidth, double tileHeight, bool fill, TileZoom zoom)
    {
        if (pictureWidth < 1 || pictureHeight < 1 || !(tileWidth > 0) || !(tileHeight > 0))
        {
            return null;
        }
        PixelRegion whole = Whole(pictureWidth, pictureHeight);
        UnitRect s = zoom.Visible(ZoomBase.Of(pictureWidth, pictureHeight, tileWidth, tileHeight, fill));
        int minX = Math.Max((int)Math.Round(s.X * pictureWidth), 0), minY = Math.Max((int)Math.Round(s.Y * pictureHeight), 0);
        int maxX = Math.Min((int)Math.Round(s.Right * pictureWidth), pictureWidth);
        int maxY = Math.Min((int)Math.Round(s.Bottom * pictureHeight), pictureHeight);
        return maxX > minX && maxY > minY ? new PixelRegion(minX, minY, maxX - minX, maxY - minY) : whole;
    }
}
